Translate the following GNU C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include<cstdio>
#include<cstring>
#include<algorithm>
#include<vector>
#include<queue>
using namespace std;

const int MAXN=15;
const int MAXM=100005;
const int MAXNODE=MAXN*MAXN*2+5;
const int INF=1000000000;
const int dx[4]={0,0,-1,1};
const int dy[4]={1,-1,0,0};

char E[MAXN][MAXN], F[MAXN][MAXN];
int n, lim, sx, sy, S, T, tot;
int idcell[MAXN][MAXN], distZ[MAXN][MAXN], mark[MAXN][MAXN];
int qq[MAXM], level[MAXNODE], it[MAXNODE];
int distC[MAXN][MAXN];
struct Pt { int x, y; } Pq[MAXM];
struct FlowEdge { int to, rev, cap; };
vector<FlowEdge> g[MAXNODE];

inline bool valid(int x, int y) {
    if (x < 0 || y < 0 || x >= n || y >= n || mark[x][y] || E[x][y] < '0' || E[x][y] > '9') return 0;
    return 1;
}

void addEdge(int u, int v, int c) {
    FlowEdge fwd = {v, (int)g[v].size(), c};
    FlowEdge rev = {u, (int)g[u].size(), 0};
    g[u].push_back(fwd);
    g[v].push_back(rev);
}

void bfsZ() {
    int l = 1, r = 0;
    memset(distZ, 60, sizeof(distZ));
    distZ[sx][sy] = 0;
    Pq[++r].x = sx; Pq[r].y = sy;
    mark[sx][sy] = 1;
    for (; l <= r; ++l) {
        int ax = Pq[l].x, ay = Pq[l].y;
        for (int k = 0; k < 4; ++k) {
            int nx = ax + dx[k], ny = ay + dy[k];
            if (valid(nx, ny)) {
                distZ[nx][ny] = distZ[ax][ay] + 1;
                mark[nx][ny] = 1;
                Pq[++r].x = nx; Pq[r].y = ny;
            }
        }
    }
}

void findLinks(int tx, int ty, int node) {
    int l = 1, r = 0;
    memset(mark, 0, sizeof(mark));
    memset(distC, 60, sizeof(distC));
    mark[tx][ty] = 1;
    distC[tx][ty] = 0;
    Pq[++r].x = tx; Pq[r].y = ty;
    for (; l <= r; ++l) {
        int ax = Pq[l].x, ay = Pq[l].y;
        for (int k = 0; k < 4; ++k) {
            int nx = ax + dx[k], ny = ay + dy[k];
            if (valid(nx, ny)) {
                distC[nx][ny] = distC[ax][ay] + 1;
                mark[nx][ny] = 1;
                if (distC[nx][ny] < distZ[nx][ny]) {
                    Pq[++r].x = nx; Pq[r].y = ny;
                }
            }
        }
    }
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (distC[i][j] <= lim && F[i][j] > '0' && F[i][j] <= '9' && distC[i][j] <= distZ[i][j])
                addEdge(node, idcell[i][j] + tot, INF);
}

bool bfsLevel() {
    memset(level, -1, sizeof(level));
    queue<int> q;
    level[S] = 0;
    q.push(S);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (const FlowEdge &e : g[u]) {
            if (e.cap > 0 && level[e.to] == -1) {
                level[e.to] = level[u] + 1;
                q.push(e.to);
            }
        }
    }
    return level[T] != -1;
}

int dfs(int u, int flow) {
    if (u == T) return flow;
    for (int &i = it[u]; i < (int)g[u].size(); ++i) {
        FlowEdge &e = g[u][i];
        if (e.cap > 0 && level[e.to] == level[u] + 1) {
            int ret = dfs(e.to, min(flow, e.cap));
            if (ret) {
                e.cap -= ret;
                g[e.to][e.rev].cap += ret;
                return ret;
            }
        }
    }
    return 0;
}

int maxflow() {
    int ans = 0;
    while (bfsLevel()) {
        memset(it, 0, sizeof(it));
        int f;
        while ((f = dfs(S, INF)) > 0) ans += f;
    }
    return ans;
}

int main() {
    scanf("%d%d", &n, &lim);
    for (int i = 0; i < n; ++i) scanf("%s", E[i]);
    for (int i = 0; i < n; ++i) scanf("%s", F[i]);

    for (sx = 0; sx < n; ++sx) {
        for (sy = 0; sy < n; ++sy)
            if (E[sx][sy] == 'Z') break;
        if (sy != n) break;
    }

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) idcell[i][j] = ++tot;

    S = 2 * tot + 1;
    T = S + 1;

    bfsZ();

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (E[i][j] > '0' && E[i][j] <= '9') {
                addEdge(S, idcell[i][j], E[i][j] - '0');
                findLinks(i, j, idcell[i][j]);
            }

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (F[i][j] > '0' && F[i][j] <= '9')
                addEdge(idcell[i][j] + tot, T, F[i][j] - '0');

    printf("%d\n", maxflow());
    return 0;
}
